def resolve_active_sites(program_code: str, default_active_sites: int, site_overrides_df) -> int:
    # pandas path
    if _PANDAS_AVAILABLE:
        scoped = site_overrides_df[
            (site_overrides_df["program_code"] == program_code)
            & (site_overrides_df["approval_state"] == "approved")
        ]

        if len(scoped) == 0:
            return int(default_active_sites)

        # highest version_no wins
        scoped = scoped.copy()
        scoped["version_no"] = pd.to_numeric(scoped["version_no"], errors="coerce")
        idx = scoped["version_no"].idxmax()
        active_sites = scoped.loc[idx, "active_sites"]
        return int(active_sites)

    # csv.DictReader fallback path: site_overrides_df is list[dict]
    best = None
    for row in site_overrides_df:
        if str(row.get("program_code")) != program_code:
            continue
        if str(row.get("approval_state")) != "approved":
            continue
        v = _to_int(row.get("version_no"), default=-1)
        if best is None or v > best[0]:
            best = (v, row)

    if best is None:
        return int(default_active_sites)

    return _to_int(best[1].get("active_sites"), default=default_active_sites)

